create extension if not exists pgcrypto;
create table campaigns(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,status text not null default 'ACTIVE',starts_at timestamptz,ends_at timestamptz,total_inventory int not null,created_at timestamptz not null default now());
create table prizes(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaigns on delete cascade,code text not null,name text not null,total_qty int not null,wheel_index int not null check(wheel_index between 0 and 6),display_order int not null,active boolean not null default true,unique(campaign_id,code));
create table participants(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaigns on delete cascade,name text not null,phone text not null,phone_normalized text not null,created_at timestamptz not null default now(),unique(campaign_id,phone_normalized));
create table prize_units(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaigns on delete cascade,prize_id uuid not null references prizes,unit_no int not null,status text not null default 'AVAILABLE' check(status in('AVAILABLE','AWARDED','CLAIMED')),awarded_at timestamptz,participant_id uuid references participants,spin_id uuid,unique(campaign_id,unit_no));
create table spins(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaigns,participant_id uuid not null references participants,prize_id uuid not null references prizes,prize_unit_id uuid not null references prize_units,request_id uuid not null unique,status text not null default 'AWARDED',created_at timestamptz not null default now(),claimed_at timestamptz,unique(campaign_id,participant_id));
alter table prize_units add constraint prize_units_spin_fk foreign key(spin_id) references spins(id);

